using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using Frociart;
internal static class CycleViewTests {
 static int checks;static void Check(bool yes,string why){if(!yes)throw new Exception(why);checks++;}
 static string Enc(Diagram d){return Convert.ToBase64String(DiagramIO.EncodeDocument(d));}
 static void Verify(FlowCycleView model,Diagram original,string baseline){var p=model.Build();Check(Enc(original)==baseline,"Projection never edits original");Check(p.Graph.Nodes.Select(n=>n.Id).Distinct().Count()==p.Graph.Nodes.Count,"Unique visual IDs");var ids=new HashSet<string>(p.Graph.Nodes.Select(n=>n.Id));Check(p.Graph.Edges.All(e=>ids.Contains(e.From)&&ids.Contains(e.To)),"No floating edge");foreach(var card in p.Cards){Check(p.Graph.Nodes.Any(n=>n.Id==card.Key&&n.Kind==NodeKind.Process),"Capsule visible");Check(card.Value.Members.All(id=>p.Owner[id]==card.Key),"Every hidden member maps to capsule");Check(p.Graph.Edges.Count(e=>e.From==card.Key)==1,"One visible exit");Check(p.Graph.Edges.Where(e=>e.From==card.Key).All(e=>e.Branch=="next"),"Exit normalized only in view");}Check(original.Nodes.All(n=>ids.Contains(n.Id)||p.Owner.ContainsKey(n.Id)),"Every node visible or represented");for(int i=0;i<p.Graph.Nodes.Count;i++)for(int j=i+1;j<p.Graph.Nodes.Count;j++){var a=FlowCanvas.GetNodeBounds(p.Graph.Nodes[i]);var b=FlowCanvas.GetNodeBounds(p.Graph.Nodes[j]);Check(!a.IntersectsWith(b),"Projected blocks do not overlap");}}
 static Diagram Loop(int kind){var d=DiagramIO.CreateBlank();return FlowLoopBuilder.Prepare(d,null,d.Edges[0].Id,FlowLoopBuilder.Spec.Default(kind)).Project;}
 [STAThread]static int Main(string[] args){try{
  for(int kind=0;kind<3;kind++){var d=Loop(kind);var info=FlowCycle.Find(d).Single();foreach(var n in d.Nodes){n.Comment="Nota di prova";if(n.Kind==NodeKind.Decision){n.TrueLabel="Ripeti";n.FalseLabel="Esci";n.TrueColor="#123456";n.FalseColor="#654321";}}d.Nodes.First(n=>n.Id==info.Check).Breakpoint=true;d.Nodes.First(n=>n.Id==info.Check).BreakpointCondition="i > 1";string before=Enc(d);var v=new FlowCycleView(d);Check(v.Cycles.Count==1&&v.Cycles[0].Kind==kind,"All loop kinds recognized");var p=v.Build();Check(p.Cards.Count==1&&p.Graph.Nodes.Count<d.Nodes.Count,"Fold reduces real visual node count");Check(p.Graph.Nodes.Single(n=>n.Id==info.Entry).Breakpoint,"Hidden breakpoint remains indicated");Verify(v,d,before);v.Set(info.Check,false);Verify(v,d,before);Check(v.Build().Graph.Edges.Count==d.Edges.Count,"Expansion restores every edge");Check(v.Build().Graph.Nodes.All(n=>n.Comment=="Nota di prova"),"Expansion retains all notes");for(int k=0;k<8;k++){v.Set(info.Check,k%2==0);Verify(v,d,before);}var broken=v.Build();broken.Graph.Nodes[0].Text="View-only edit";broken.Graph.Edges.Clear();Verify(v,d,before);Check(Enc(DiagramIO.Clone(d))==before,"Native save representation unchanged");}
  var nested=FlowPseudocode.Decode("PER i DA 1 A 2 FAI\nPER j DA 1 A 2 FAI\nSTAMPA i * 10 + j\nFINE PER\nFINE PER");string snap=Enc(nested);var nv=new FlowCycleView(nested);Check(nv.Cycles.Count==2,"Nested loops inventoried");var outer=nv.Cycles.OrderByDescending(c=>c.Members.Count).First();var inner=nv.Cycles.OrderBy(c=>c.Members.Count).First();Check(nv.Build().Cards.Count==1,"Only outer capsule visible initially");nv.Set(outer.Check,false);Check(nv.Build().Cards.Values.Single().Check==inner.Check,"Inner stays folded when outer opens");Verify(nv,nested,snap);nv.All(true);nv.Set(inner.Check,false);Check(nv.Folded.Count==0,"Opening nested loop opens its ancestors");Verify(nv,nested,snap);nv.All(true);nv.Set(inner.Check,true);Check(nv.Build().Cards.Values.Single().Check==inner.Check,"Choosing hidden inner loop reveals it");Verify(nv,nested,snap);
  var invalid=DiagramIO.Clone(nested);var start=invalid.Nodes.First(n=>n.Kind==NodeKind.Start);invalid.Edges.Add(new FlowEdge{From=start.Id,To=outer.BodyEntry});var iv=new FlowCycleView(invalid);Check(!iv.Cycles.Any(c=>c.Check==outer.Check),"Multiple entries not folded");Verify(iv,invalid,Enc(invalid));
  var free=DiagramIO.CreateBlank();var self=new FlowNode{Kind=NodeKind.Process,Text="x=1",X=800};free.Nodes.Add(self);free.Edges.Add(new FlowEdge{From=self.Id,To=self.Id});var fv=new FlowCycleView(free);Check(fv.Cycles.Count==0&&fv.Build().Graph.Edges.Any(e=>e.From==self.Id&&e.To==self.Id),"Ordinary self loop preserved");Verify(fv,free,Enc(free));
  var empty=new Diagram();var ev=new FlowCycleView(empty);Check(ev.Build().Graph.Nodes.Count==0,"Empty graph safe");
  var large=Loop(1);var cycle=FlowCycle.Find(large).Single();var tail=large.Edges.First(e=>e.To==cycle.Check&&cycle.Members.Contains(e.From));string previous=tail.From;large.Edges.Remove(tail);for(int i=large.Nodes.Count;i<500;i++){var n=new FlowNode{Kind=NodeKind.Process,Text="i=i+0"};large.Nodes.Add(n);large.Edges.Add(new FlowEdge{From=previous,To=n.Id});previous=n.Id;}large.Edges.Add(new FlowEdge{From=previous,To=cycle.Check});var clock=Stopwatch.StartNew();var lv=new FlowCycleView(large);var lp=lv.Build();Check(lv.Cycles.Count==1&&lp.Graph.Nodes.Count<6,"500 block loop compacts");Check(clock.ElapsedMilliseconds<15000,"Bounded inventory/layout time");Console.WriteLine("LARGE_MS="+clock.ElapsedMilliseconds);Verify(lv,large,Enc(large));
  Console.WriteLine("CYCLE_VIEW_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
